import { useCallback, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const DAY_MS = 24 * 60 * 60 * 1000;

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function shiftDays(days: number): Date {
  return startOfDay(new Date(Date.now() - days * DAY_MS));
}

const presets: { id: string; label: string; resolve: () => Date }[] = [
  { id: 'today', label: 'Сегодня', resolve: () => shiftDays(0) },
  { id: 'yesterday', label: 'Вчера', resolve: () => shiftDays(1) },
  { id: 'week-ago', label: 'Неделя назад', resolve: () => shiftDays(7) },
];

function isSameDay(a: Date | null | undefined, b: Date): boolean {
  return !!a && startOfDay(a).getTime() === b.getTime();
}

export default function ReportDatePicker({ value, defaultValue = null, onChange }: ReportDatePickerProps) {
  const [internal, setInternal] = useState<Date | null>(defaultValue);
  const current = value !== undefined ? value : internal;

  const commit = useCallback(
    (next: Date | null) => {
      if (value === undefined) setInternal(next);
      onChange?.(next);
    },
    [onChange, value],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxWidth: '320px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }} role="group" aria-label="Быстрый выбор даты отчёта">
        {presets.map((preset) => {
          const presetDate = preset.resolve();
          return (
            <JxChip
              key={preset.id}
              role="button"
              tabIndex={0}
              aria-pressed={isSameDay(current, presetDate)}
              active={isSameDay(current, presetDate)}
              onClick={() => commit(presetDate)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  commit(presetDate);
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar locale="ru-RU" value={current} onValueChange={commit} aria-label="Дата отчёта" />

      <p
        style={{
          margin: 0,
          font: 'inherit',
          fontFamily: 'var(--jx-font-sans)',
          color: current ? 'var(--jx-text)' : 'var(--jx-text-2)',
        }}
        aria-live="polite"
      >
        {current
          ? `Отчёт за ${current.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' })}`
          : 'Дата не выбрана — выберите день в календаре или быстрый вариант выше.'}
      </p>
    </div>
  );
}

